SELECT COUNT(*) AS total_admissions, CAST(COUNT(DISTINCT CASE WHEN age(CURRENT_DATE, p.dob) BETWEEN 80 AND 90 AND p.gender = 'M' AND d.icd_code IN ('ACS') THEN a.hadm_id END) AS FLOAT) / NULLIF(COUNT(*), 0) AS proportion_of_admissions, AVG(i.los) AS average_length_of_stay FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id JOIN icustays i ON a.stay_id = i.stay_id WHERE age(CURRENT_DATE, p.dob) BETWEEN 85 AND 86 AND p.gender = 'M' AND d.icd_code IN ('ACS') AND i.category IN ('Normal', 'Borderline', 'Myocardial Injury') GROUP BY a.subject_id;